#!/usr/bin/env python3
import pathlib
import subprocess
import tempfile

ROOT = pathlib.Path(__file__).resolve().parents[1]
PARSER = ROOT / "patched-src" / "FloatingImportParser.java"
assert PARSER.is_file(), f"Missing parser source: {PARSER}"

with tempfile.TemporaryDirectory(prefix="floating-import-test-") as temp:
    temp_path = pathlib.Path(temp)
    harness = temp_path / "FloatingImportParserTest.java"
    harness.write_text("import java.util.Arrays;\nimport java.util.List;\n\npublic class FloatingImportParserTest {\n    private static void check(boolean condition, String message) {\n        if (!condition) throw new AssertionError(message);\n    }\n\n    private static String msg(String name, String amount, String time) {\n        return \"ابو علوي رقم جديد\\nاسم المستلم: \" + name\n                + \"\\nالمبلغ: \" + amount + \"\\n\" + time + \"\\n\";\n    }\n\n    public static void main(String[] args) {\n        String a = msg(\"محمد صالح احمد الجوهي\", \"500\", \"7:15 م\");\n        String b = msg(\"علي سالم عبدالله باعوض\", \"250\", \"7:16 م\");\n        String c = msg(\"سالم عمر احمد بن ماضي\", \"550\", \"7:17 م\");\n\n        // The older page contains yesterday's history followed by today's\n        // messages; the newer page overlaps the last message from the old page.\n        String olderPage = \"رسائل قديمة\\nأمس\\n\" + a + b;\n        String newerPage = b + c;\n        List<FloatingImportParser.Transfer> parsed =\n                FloatingImportParser.parsePages(Arrays.asList(newerPage, olderPage));\n        check(parsed.size() == 3, \"Expected 3 unique today messages after overlap merge; got \" + parsed.size());\n        check(\"محمد صالح احمد الجوهي\".equals(parsed.get(0).name), \"First recipient was not paired with its own amount\");\n        check(\"500\".equals(parsed.get(0).amount), \"First amount mismatch\");\n        check(\"19:15:00\".equals(parsed.get(0).time), \"Arabic PM time conversion failed\");\n        check(\"علي سالم عبدالله باعوض\".equals(parsed.get(1).name), \"Second recipient mismatch\");\n        check(\"250\".equals(parsed.get(1).amount), \"Second amount mismatch\");\n        check(\"سالم عمر احمد بن ماضي\".equals(parsed.get(2).name), \"Third recipient mismatch\");\n\n        // Identical legitimate messages within one page remain separate rows.\n        List<FloatingImportParser.Transfer> repeated =\n                FloatingImportParser.parsePages(Arrays.asList(a + a));\n        check(repeated.size() == 2, \"Two real repeated messages in one page must remain two occurrences\");\n\n        String storedOne = \"2026-11-18\\t19:15:37\\tمحمد صالح احمد الجوهي\\t500\";\n        List<FloatingImportParser.Transfer> onlyOneNew =\n                FloatingImportParser.onlyNewOccurrences(repeated, storedOne, \"2026-11-18\");\n        check(onlyOneNew.size() == 1, \"A rescan should add only the additional duplicate occurrence\");\n        String storedTwo = storedOne + \"\\n2026-11-18\\t19:15:58\\tمحمد صالح احمد الجوهي\\t500\";\n        check(FloatingImportParser.onlyNewOccurrences(repeated, storedTwo, \"2026-11-18\").isEmpty(),\n                \"A repeated full-day scan must not add rows already stored\");\n\n        String arabicDigits = msg(\"خالد محمد صالح باوزير\", \"٥٠٠\", \"٧:٣٠ م\");\n        List<FloatingImportParser.Transfer> arabic =\n                FloatingImportParser.parsePages(Arrays.asList(arabicDigits));\n        check(arabic.size() == 1, \"Arabic-Indic amount/time should parse\");\n        check(\"500\".equals(arabic.get(0).amount), \"Arabic-Indic amount normalization failed\");\n        check(\"19:30:00\".equals(arabic.get(0).time), \"Arabic-Indic time normalization failed\");\n\n        // An amount from one sender block must never be paired with a name\n        // from another block, and messages without a visible time are skipped.\n        String nameOnly = \"ابو علوي رقم جديد\\nاسم المستلم: عبدالله صالح احمد\\n\";\n        String amountOnly = \"ابو علوي رقم جديد\\nالمبلغ: 900\\n8:00 م\\n\";\n        check(FloatingImportParser.parsePages(Arrays.asList(nameOnly + amountOnly)).isEmpty(),\n                \"Parser must not cross-pair fields between separate messages\");\n\n        String noTime = \"ابو علوي رقم جديد\\nاسم المستلم: عبدالله صالح احمد\\nالمبلغ: 900\\n\";\n        check(FloatingImportParser.parsePages(Arrays.asList(noTime)).isEmpty(),\n                \"Parser must not invent the current time for a message with no visible timestamp\");\n\n        check(FloatingImportParser.fingerprint(\"2026-11-18\", \"19:15:00\",\n                \"محمد صالح احمد الجوهي\", \"500\").equals(\n                FloatingImportParser.fingerprint(\"2026-11-18\", \"19:15:59\",\n                        \"محمد صالح احمد الجوهي\", \"500\")),\n                \"Fingerprint should use message minute to match notification timestamps\");\n\n        System.out.println(\"Floating import parser tests passed: message pairing, timestamps, overlap, yesterday cutoff, and occurrence-aware rescans.\");\n    }\n}\n", encoding="utf-8")
    subprocess.run(
        ["javac", "-encoding", "UTF-8", "-d", str(temp_path), str(PARSER), str(harness)],
        check=True,
    )
    subprocess.run(
        ["java", "-cp", str(temp_path), "FloatingImportParserTest"],
        check=True,
    )

